// ===========================================================================
//  BOT NHẬN LỆNH - KIỂU POLLING (không cần webhook / không cần VPS mở cổng).
//  Mỗi phút n8n GỌI RA Telegram lấy tin mới -> xử lý -> trả lời. Chỉ gọi ra
//  ngoài nên chạy được ở mọi setup. Sửa 3 dòng dưới nếu cần.
// ===========================================================================
const TOKEN = 'PASTE_BOT_TOKEN_HERE'; // token bot (BotFather) - DÁN VÀO ĐÂY
const OWNER = 5239928968;             // chỉ Chat ID này dùng được bot
const NAV   = 5000000;                // tài sản ròng (ĐỒNG)
const MAX_POS_PCT = 100;              // trần % NAV / 1 vị thế
const RISK_PCT_DEF = 1.5;             // % NAV chấp nhận mất nếu cắt lỗ
// ===========================================================================

const api  = 'https://api.telegram.org/bot' + TOKEN;
const http = (o) => this.helpers.httpRequest(o);

const fmtM = (d) => (d / 1e6).toFixed(d < 1e7 ? 2 : 1) + ' triệu';
const fmtP = (k) => Math.round(k * 1000).toLocaleString('vi-VN') + 'đ';

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const hBar = { 'User-Agent': UA, 'Accept': '*/*' };
const hFin = { 'User-Agent': UA, 'Accept': 'application/json', 'Referer': 'https://dstock.vndirect.com.vn/' };
const to = Math.floor(Date.now() / 1000), from = to - 60 * 60 * 24 * 200;

// chuẩn hoá về ĐỒNG (vài nguồn trả nghìn đồng: 70.0 -> ×1000)
const normBars = (r) => {
  if (!r || !Array.isArray(r.c) || !r.c.length) return r;
  const last = r.c[r.c.length - 1];
  if (last > 0 && last < 1000) for (const k of ['c', 'o', 'h', 'l']) if (Array.isArray(r[k])) r[k] = r[k].map(x => x * 1000);
  return r;
};
const fetchBars = async (t) => {
  try { const r = await http({ method: 'GET', url: 'https://services.entrade.com.vn/chart-api/v2/ohlcs/stock', qs: { symbol: t, from, to, resolution: '1D' }, headers: hBar, json: true, timeout: 15000 }); if (r && Array.isArray(r.c) && r.c.length) return normBars(r); } catch (e) {}
  try { const r = await http({ method: 'GET', url: 'https://dchart-api.vndirect.com.vn/dchart/history', qs: { symbol: t, resolution: 'D', from, to }, headers: { ...hBar, Referer: 'https://dchart.vndirect.com.vn/' }, json: true, timeout: 15000 }); if (r && Array.isArray(r.c) && r.c.length) return normBars(r); } catch (e) {}
  return null;
};
const fetchPE = async (t) => {
  try {
    const r = await http({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/ratios?q=code:' + t + '~itemCode:51006,1000043&sort=reportDate:desc&size=10', headers: hFin, json: false, timeout: 12000 });
    let p; try { p = typeof r === 'string' ? JSON.parse(r) : r; } catch (e) { p = null; }
    const m = {}; for (const d of ((p && p.data) || [])) if (!(d.ratioCode in m)) m[d.ratioCode] = d.value;
    return { pe: m['PRICE_TO_EARNINGS'], pe5: m['PRICE_TO_EARNINGS_AVG_CR_5Y'] };
  } catch (e) { return {}; }
};
const fetchFlow = async (t) => {
  try { const r = await http({ method: 'GET', url: 'https://api-finfo.vndirect.com.vn/v4/foreigns?q=code:' + t + '&size=5&sort=tradingDate:desc', headers: hFin, json: true, timeout: 12000 }); return ((r && r.data) || []).map(x => (x.netVal || 0) / 1e9); } catch (e) { return []; }
};

const tickOf = (p) => p < 10000 ? 10 : p < 50000 ? 50 : 100;
const roundT = (p) => { const t = tickOf(p); return Math.round(p / t) * t; };
const pivots = (arr, w, kind) => {
  const r = [];
  for (let i = w; i < arr.length - w; i++) { let ok = true; for (let k = i - w; k <= i + w; k++) { if (k === i) continue; if (kind === 'low' ? arr[k] < arr[i] : arr[k] > arr[i]) { ok = false; break; } } if (ok) r.push({ i, v: arr[i] }); }
  return r;
};
const dstr = (sec) => new Date(sec * 1000).toLocaleDateString('en-CA', { timeZone: 'Asia/Ho_Chi_Minh' });
const deriveLevels = (bars, entryOverrideK) => {
  const n = bars.c.length, lows = bars.l, highs = bars.h, times = bars.t;
  const closeD = bars.c[n - 1];
  const entryD = entryOverrideK > 0 ? entryOverrideK * 1000 : closeD;
  const lookI = Math.max(0, n - 130);
  const pl = pivots(lows, 3, 'low').filter(p => p.i >= lookI && p.v < entryD * 0.997);
  const ph = pivots(highs, 3, 'high').filter(p => p.i >= lookI && p.v > entryD * 1.003);
  const note = [];
  let sup, supDate = null;
  if (pl.length) { const b = pl.reduce((a, x) => x.v > a.v ? x : a); sup = b.v; supDate = dstr(times[b.i]); }
  else { sup = Math.min(...lows.slice(Math.max(0, n - 20))); note.push('hỗ trợ tạm tính = đáy 20 phiên'); }
  let res, resDate = null;
  if (ph.length) { const b = ph.reduce((a, x) => x.v < a.v ? x : a); res = b.v; resDate = dstr(times[b.i]); }
  else { const hi = Math.max(...highs.slice(lookI)); if (hi > entryD * 1.01) { res = hi; note.push('kháng cự tạm tính = đỉnh 6 tháng'); } else { res = entryD * 1.08; note.push('⚠️ giá ở vùng đỉnh, mục tiêu tạm +8%'); } }
  let stopD = roundT(sup * 0.985); if (stopD >= entryD) stopD = roundT(entryD * 0.92);
  let targetD = roundT(res); const eD = roundT(entryD);
  if (targetD <= eD) { targetD = roundT(eD * 1.08); note.push('mục tiêu điều chỉnh +8%'); }
  return { eD, stopD, targetD, supD: roundT(sup), resD: roundT(res), supDate, resDate, closeD: roundT(closeD), note };
};

// ---- xử lý 1 lệnh -> trả về chuỗi trả lời -------------------------------
const handle = async (rawText, chatId) => {
  if (String(chatId) !== String(OWNER)) return '⛔ Bot riêng tư.';
  const text = (rawText || '').trim();
  const help = '🤖 *Bot CK — chỉ cần gõ MÃ*\n\n'
    + '🧮 `/size MÃ`  _vd: /size BID_ — tự tính vùng giá + khối lượng & R:R\n'
    + '🧭 `/check MÃ`  _vd: /check FPT_ — tự tính vùng giá + bảng 7 câu\n\n'
    + '✍️ Tự nhập: `/size MÃ vào cắtlỗ mụctiêu` _(nghìn đồng)_\n'
    + '_Mức bot đề xuất là gợi ý kỹ thuật, không phải lệnh mua._';
  if (!text || /^\/(start|help)\b/i.test(text)) return help;
  const parts = text.split(/\s+/);
  const cmd = parts[0].toLowerCase().replace(/@.*$/, '');
  if (cmd !== '/size' && cmd !== '/check') return '❓ Lệnh không hiểu.\n\n' + help;
  const TICKER = (parts[1] || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (!TICKER) return '⚠️ Thiếu mã. Gõ: `/size BID` hoặc `/check FPT`';
  const aEntry = parts[2] != null ? parseFloat(parts[2]) : NaN;
  const aStop = parts[3] != null ? parseFloat(parts[3]) : NaN;
  const aTarget = parts[4] != null ? parseFloat(parts[4]) : NaN;
  const RISK_PCT = (parts[5] != null && parseFloat(parts[5]) > 0) ? parseFloat(parts[5]) : RISK_PCT_DEF;

  const manual = aEntry > 0 && aStop > 0;
  let ENTRY, STOP, TARGET, prov;
  if (manual) {
    if (!(aStop < aEntry)) return '⚠️ Cắt lỗ phải THẤP HƠN giá vào.';
    ENTRY = aEntry; STOP = aStop; TARGET = aTarget > aEntry ? aTarget : 0; prov = '✍️ _Mức anh tự nhập_';
  } else {
    const bars = await fetchBars(TICKER);
    if (!bars || !Array.isArray(bars.c) || bars.c.length < 12) return '🔴 Không lấy được dữ liệu giá *' + TICKER + '* (API lỗi hoặc mã sai).\nThử lại sau, hoặc nhập tay: `/' + cmd.slice(1) + ' ' + TICKER + ' vào cắtlỗ mụctiêu`';
    const d = deriveLevels(bars, aEntry);
    ENTRY = d.eD / 1000; STOP = d.stopD / 1000; TARGET = d.targetD / 1000;
    prov = '📐 *Mức bot tự tính:*\n· Vào ≈ giá hiện tại ' + fmtP(d.closeD / 1000) + '\n· Cắt lỗ ' + fmtP(STOP) + ' _(dưới hỗ trợ ' + fmtP(d.supD / 1000) + (d.supDate ? ' lập ' + d.supDate : '') + ')_\n· Mục tiêu ' + fmtP(TARGET) + ' _(kháng cự ' + fmtP(d.resD / 1000) + (d.resDate ? ' lập ' + d.resDate : '') + ')_' + (d.note.length ? '\n· ' + d.note.join('; ') : '');
  }

  const entryD = ENTRY * 1000, riskPerShare = (ENTRY - STOP) * 1000;
  const byRisk = Math.floor((NAV * RISK_PCT / 100) / riskPerShare / 100) * 100;
  const byCap = Math.floor((NAV * MAX_POS_PCT / 100) / entryD / 100) * 100;
  const shares = Math.max(0, Math.min(byRisk, byCap));
  const lotCost = entryD * 100;
  const rr = TARGET > ENTRY ? (TARGET - ENTRY) / (ENTRY - STOP) : null;

  if (cmd === '/size') {
    const L = ['🧮 *SIZING — ' + TICKER + '*', prov, '_NAV ' + fmtM(NAV) + ' · rủi ro ' + RISK_PCT + '%_', ''];
    if (shares <= 0) { L.push('→ Theo quy tắc rủi ro: chưa nên mua (chưa đủ 1 lô).'); L.push(lotCost <= NAV ? '⚠️ Tối thiểu 1 lô = ' + fmtM(lotCost) + ' (' + (lotCost / NAV * 100).toFixed(0) + '% NAV → tập trung rất cao).' : '🔴 NAV không đủ 1 lô (' + fmtM(lotCost) + ').'); }
    else { L.push('→ *MUA ' + shares.toLocaleString('vi-VN') + ' cp* (' + (shares / 100) + ' lô) = ' + fmtM(shares * entryD) + ' (' + (shares * entryD / NAV * 100).toFixed(0) + '% NAV)'); L.push('→ Rủi ro thực nếu cắt lỗ: *' + fmtM(shares * riskPerShare) + '* (' + (shares * riskPerShare / NAV * 100).toFixed(2) + '% NAV)'); }
    if (rr != null) L.push('→ *R:R ' + rr.toFixed(2) + '*' + (rr < 2 ? ' ⚠️ mỏng (<2)' : ' ✓ ổn'));
    L.push(''); L.push('_Số bot tính là điểm khởi đầu — anh xem chart xác nhận trước khi đặt lệnh._');
    return L.join('\n');
  }

  const pe = await fetchPE(TICKER);
  let q2 = '_thiếu P/E_';
  if (pe.pe > 0 && pe.pe5 > 0) { const k = pe.pe / pe.pe5; q2 = 'P/E ' + pe.pe.toFixed(1) + ' vs TB5N ' + pe.pe5.toFixed(1) + ' → ' + (k <= 0.85 ? '🟢 RẺ so lịch sử' : k >= 1.15 ? '🔴 ĐẮT so lịch sử' : '🟡 quanh TB'); }
  else if (pe.pe > 0) q2 = 'P/E ' + pe.pe.toFixed(1) + ' _(thiếu TB lịch sử)_';
  const nets = await fetchFlow(TICKER);
  let q4 = '_không lấy được_';
  if (nets.length) { const dir = nets[0] > 1 ? 1 : nets[0] < -1 ? -1 : 0; let st = 0; for (const v of nets) { const s = v > 1 ? 1 : v < -1 ? -1 : 0; if (s === dir && dir) st++; else break; } q4 = 'phiên gần nhất ' + nets[0].toFixed(1) + ' tỷ' + (st >= 2 ? ' · ' + (dir > 0 ? 'GOM' : 'XẢ') + ' ' + st + ' phiên' : '') + ' · tổng 5p ' + nets.reduce((a, b) => a + b, 0).toFixed(1) + ' tỷ'; }
  const q6 = (shares >= 100 ? 'mua ' + shares.toLocaleString('vi-VN') + ' cp (' + (shares * entryD / NAV * 100).toFixed(0) + '% NAV)' : (lotCost <= NAV ? '⚠️ chỉ đủ ~1 lô (' + (lotCost / NAV * 100).toFixed(0) + '% NAV)' : '🔴 NAV không đủ 1 lô')) + ' · R:R ' + (rr ? rr.toFixed(2) + (rr < 2 ? ' ⚠️' : '') : 'n/a');

  const L = ['🧭 *BẢNG 7 CÂU — ' + TICKER + '*', prov, ''];
  L.push('① *Hiểu DN?* → DN này kiếm tiền bằng cách nào? Nói gọn 1 câu được không?');
  L.push('   _Không nói được → chưa hiểu → bỏ qua._');
  L.push('② Rẻ/đắt? ✅ ' + q2);
  L.push('③ *Luận điểm?* → Mua vì TIN điều gì sắp xảy ra? Dấu hiệu nào cho thấy mình SAI?');
  L.push('   _Viết được câu "nếu… thì tôi sai" mới nên mua._');
  L.push('④ Bối cảnh? ✅ Khối ngoại: ' + q4);
  L.push('⑤ *Thời điểm?* → Có xúc tác để tăng BÂY GIỜ (KQKD, cổ tức, hợp đồng…), hay chỉ "thấy rẻ ham" = bắt dao rơi?');
  L.push('⑥ Kích thước & R:R? ✅ ' + q6);
  L.push('⑦ Thoát? ✅ Cắt lỗ ' + fmtP(STOP) + (TARGET ? ' · Mục tiêu ' + fmtP(TARGET) : ''));
  L.push('');
  L.push('📝 ②④⑥⑦ bot lo (định lượng). ①③⑤ là VIỆC CỦA ANH (định tính) — đây mới là phần bảo vệ tiền của anh.');
  L.push('💡 Bí ①③⑤? Chạy *"🔬 Soi sâu 1 mã"* (CK·04) — AI viết nháp sẵn 3 câu này, anh chỉ đọc & duyệt.');
  L.push('_Mức giá là gợi ý kỹ thuật, không phải khuyến nghị mua/bán._');
  return L.join('\n');
};

// ---- gửi trả lời (markdown lỗi thì gửi lại dạng thường) ------------------
const send = async (chatId, msg) => {
  try { await http({ method: 'POST', url: api + '/sendMessage', body: { chat_id: chatId, text: msg, parse_mode: 'Markdown' }, json: true, timeout: 15000 }); }
  catch (e) { try { await http({ method: 'POST', url: api + '/sendMessage', body: { chat_id: chatId, text: msg }, json: true, timeout: 15000 }); } catch (e2) {} }
};

// =================== VÒNG LẶP POLLING ====================================
const sd = $getWorkflowStaticData('global');

if (!sd.tgInit) { try { await http({ method: 'POST', url: api + '/deleteWebhook', json: true, timeout: 10000 }); } catch (e) {} sd.tgInit = true; }

let updates = [];
try {
  const r = await http({ method: 'GET', url: api + '/getUpdates', qs: { offset: sd.tgOffset || 0, timeout: 0, allowed_updates: JSON.stringify(['message']) }, json: true, timeout: 15000 });
  updates = (r && r.result) || [];
} catch (e) { return [{ json: { ok: false, error: 'getUpdates: ' + (e.message || String(e)) } }]; }

if (!updates.length) return [{ json: { ok: true, processed: 0 } }];

// lần đầu: bỏ qua tồn đọng (tránh trả lời loạt tin test cũ)
if (sd.tgOffset === undefined) { sd.tgOffset = updates[updates.length - 1].update_id + 1; return [{ json: { ok: true, drained: updates.length } }]; }

const done = [];
for (const u of updates) {
  sd.tgOffset = Math.max(sd.tgOffset || 0, u.update_id + 1);
  const m = u.message; if (!m || !m.text) continue;
  const reply = await handle(m.text, m.chat && m.chat.id);
  await send(m.chat.id, reply);
  done.push({ text: m.text, chat: m.chat && m.chat.id });
}
return done.length ? done.map(d => ({ json: d })) : [{ json: { ok: true, processed: 0 } }];
